<?php
require_once __DIR__.'/../includes/member.php';$user=require_login();if($user['role']==='admin')redirect('admin/dashboard.php');
expire_unpaid_delivery_requests((int)$user['id']);
$id=(int)($_GET['id']??$_POST['id']??0);$item=one('SELECT br.*,b.title,b.book_id FROM borrowings br JOIN books b ON b.id=br.book_id WHERE br.id=? AND br.user_id=? AND br.fulfillment_method="delivery"',[$id,$user['id']]);
if($_SERVER['REQUEST_METHOD']==='POST'&&$item&&$item['status']==='awaiting_payment'){$method=$_POST['payment_method']??'';if(!in_array($method,['qris','virtual_account'],true)){flash('Pilih metode pembayaran.','error');redirect('member/pembayaran.php?id='.$id);}$paidAt=(new DateTimeImmutable('now'))->format('Y-m-d H:i:s');execute("UPDATE borrowings SET payment_method=?,paid_at=?,status='in_transit' WHERE id=? AND user_id=? AND status='awaiting_payment'",[$method,$paidAt,$id,$user['id']]);flash('Pembayaran dummy berhasil. Paket sedang disiapkan.');redirect('member/pelacakan.php?id='.$id);}
member_start('Pembayaran Peminjaman',$user,'peminjaman.php'); ?>
<section class="member-section"><span class="member-kicker">PEMBAYARAN PENGANTARAN</span><h1>Pilih metode pembayaran</h1><?php if($item&&$item['status']==='awaiting_payment'):?><p><?=e($item['title'])?> · Biaya ekspedisi <b><?=rupiah((int)$item['shipping_fee'])?></b></p><p>Selesaikan pembayaran sebelum <?=date_id($item['payment_deadline'],true)?>.</p><form method="post"><input type="hidden" name="id" value="<?=$id?>"><label class="payment-choice"><input type="radio" name="payment_method" value="qris" required> QRIS</label><label class="payment-choice"><input type="radio" name="payment_method" value="virtual_account" required> Bank Virtual Account</label><button type="submit">Selesai melakukan pembayaran</button></form><?php elseif($item&&$item['status']==='cancelled'):?><p>Batas pembayaran tiga jam sudah lewat. Permintaan dihapus dan stok buku dikembalikan.</p><?php elseif($item&&in_array($item['status'],['in_transit','active'],true)):?><p>Pembayaran sudah tercatat. <a href="<?=e(url('member/pelacakan.php?id='.$id))?>">Lihat pelacakan paket</a>.</p><?php else:?><p>Transaksi tidak ditemukan.</p><?php endif;?></section><?php member_end(); ?>
